def test_ability_merged_links_and_navigation():
        """讨论稿与原表均可从模块索引找到，文档及索引链接指向实际文件。"""
        text = DOCUMENT.read_text(encoding="utf-8")
        for target in re.findall(r"\]\(([^)]+)\)", text):
